function value = rfdude_pll_parse_value(text)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Parse numeric literals and start:step:stop vectors without executing code.
text=strtrim(text);
if isempty(text)
    error('Enter a numeric value or vector');
end
if text(1)=='[' && text(end)==']'
    text=strtrim(text(2:end-1));
end
parts=regexp(text,'[,\s]+','split');
value=[];
for k=1:numel(parts)
    terms=strsplit(parts{k},':');
    if isempty(parts{k}) || numel(terms)>3
        error('Use numeric literals, lists, or start:step:stop');
    end
    numbers=zeros(1,numel(terms));
    for j=1:numel(terms)
        if isempty(regexp(terms{j},'^[+-]?((\d+\.?\d*|\.\d+)([eE][+-]?\d+)?|[iI][nN][fF])$','once'))
            error('Invalid numeric literal: %s',terms{j});
        end
        numbers(j)=str2double(terms{j});
    end
    if numel(numbers)==1
        piece=numbers;
    else
        if any(~isfinite(numbers))
            error('Vector ranges must be finite');
        end
        if numel(numbers)==2
            numbers=[numbers(1) 1 numbers(2)];
        end
        if numbers(2)==0 || (numbers(3)-numbers(1))/numbers(2)<0
            error('Range step must be nonzero and point toward the endpoint');
        end
        count=floor((numbers(3)-numbers(1))/numbers(2))+1;
        if count>100000
            error('Numeric vectors are limited to 100000 entries');
        end
        piece=numbers(1):numbers(2):numbers(3);
    end
    value=[value piece];
    if numel(value)>100000
        error('Numeric vectors are limited to 100000 entries');
    end
end
end
